  return bird;
}

function axisAngleQuat(angle) {
  return new THREE.Quaternion().setFromAxisAngle(X_AXIS, angle);
}

/**
 * Creates an AnimationClip flapping both wings.
 *
 * Keys at 0%, 25%, 50%, 75%, 100% of the cycle:
 *   down (-maxAngle), flat (0), up (+maxAngle), flat (0), down (-maxAngle)
 * The right wing is mirrored about the body plane (the XZ plane): a rotation
 * by +a about +X mirrors to a rotation by -a.
 */
export function makeFlapClip(durationSec = 0.8, maxAngle = 1.1) {
  const times = [
    0,
    durationSec * 0.25,
    durationSec * 0.5,
    durationSec * 0.75,
    durationSec,
  ];

  const leftAngles = [-maxAngle, 0, maxAngle, 0, -maxAngle];
  const rightAngles = [maxAngle, 0, -maxAngle, 0, maxAngle]; // mirror

  const leftValues = [];
  const rightValues = [];
  for (let i = 0; i < times.length; i++) {
    const ql = axisAngleQuat(leftAngles[i]);
    leftValues.push(ql.x, ql.y, ql.z, ql.w);
    const qr = axisAngleQuat(rightAngles[i]);
    rightValues.push(qr.x, qr.y, qr.z, qr.w);
  }

  return new THREE.AnimationClip('flap', durationSec, [
    new THREE.QuaternionKeyframeTrack('wingL.quaternion', times.slice(), leftValues),
    new THREE.QuaternionKeyframeTrack('wingR.quaternion', times.slice(), rightValues),
  ]);
}

/**
 * Starts the flap animation on the given bird. Returns an AnimationMixer
 * with the flap clip playing on an infinite LoopRepeat loop.
 */
export function startFlap(bird) {
  const mixer = new THREE.AnimationMixer(bird);
  const action = mixer.clipAction(makeFlapClip());
  action.setLoop(THREE.LoopRepeat, Infinity);
