result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/bird.test.js", "content": "import { describe, expect, it } from 'vitest';
import * as THREE from 'three';
import { buildBird, makeFlapClip, startFlap } from '../src/bird.js';

const DT = 0.05;

function wingOf(bird, name) {
  return bird.getObjectByName(name);
}

/** Signed rotation angle about the X axis for a pure-X-axis quaternion. */
function xAngle(q) {
  return 2 * Math.atan2(q.x, q.w);
}

/** Steps the mixer in 0.05s increments and records quaternions per step. */
function sample(bird, totalTime) {
  const mixer = startFlap(bird);
  const steps = Math.round(totalTime / DT);
  const samples = [];
  for (let i = 0; i <= steps; i++) {
    const t = i * DT;
    samples.push({
      t,
      left: wingOf(bird, 'wingL').quaternion.clone(),
      right: wingOf(bird, 'wingR').quaternion.clone(),
    });
    if (i < steps) mixer.update(DT);
  }
  return samples;
}

describe('bird flap animation', () => {
  it('clip duration is exactly 0.8', () => {
    expect(makeFlapClip().duration).toBe(0.8);
  });

  it('buildBird exposes wingL and wingR', () => {
    const bird = buildBird();
    expect(wingOf(bird, 'wingL')).toBeInstanceOf(THREE.Mesh);
    expect(wingOf(bird, 'wingR')).toBeInstanceOf(THREE.Mesh);
  });

  it('at t = 0.4 (half cycle) wingL angle is maxAngle', () => {
    const maxAngle = 1.1;
    const bird = buildBird();
    const samples = sample(bird, 0.4);
    const last = samples[samples.length - 1];
    expect(last.t).toBeCloseTo(0.4, 10);
    expect(xAngle(last.left)).toBeCloseTo(maxAngle, 1e-2);
  });

  it('at t = 0.8 the pose wraps back to the start pose (LoopRepeat)', () => {
    const bird = buildBird();
    const samples = sample(bird, 0.8);
    const start = samples[0].left;
    const end = samples[samples.length - 1].left;
    // Same pose: angular difference below tolerance.
    expect(start.angleTo(end)).toBeLessThan(1e-2);
  });

  it('t = 1.2 equals t = 0.4 (loop wrap)', () => {
    const bird = buildBird();
    const samples = sample(bird, 1.2);
    const at04 = samples.find((s) => Math.abs(s.t - 0.4) < 1e-9).left;
    const at12 = samples[samples.length - 1].left;
    expect(samples[samples.length - 1].t).toBeCloseTo(1.2, 10);
    expect(at04.angleTo(at12)).toBeLessThan(1e-2);
  });

  it('wingR mirrors wingL about the body plane (conjugate) at 10 sampled times', () => {
    const bird = buildBird();
    const mixer = startFlap(bird);
    const expectedQ = new THREE.Quaternion();
    for (let i = 0; i < 10; i++) {
      mixer.update((makeFlapClip().duration / 10));
      const left = wingOf(bird, 'wingL').quaternion;
      const right = wingOf(bird, 'wingR').quaternion;
      // Mirror across the XZ body plane: q_right = conj(q_left)
      expectedQ.copy(left).conjugate();
      expect(right.angleTo(expectedQ)).toBeLessThan(1e-6);
    }
  });
});
"})
